# -*- coding: utf-8 -*-
"""index.html을 조선시대 통합·요약 노트·용어 풀이 구조로 고친다(한 번만 실행; 이미 적용됐으면 멈춘다)."""
import os, re, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
P = os.path.join(ROOT, 'index.html')
s = open(P, encoding='utf-8').read()
if 'HANQ_STUDY' in s:
    sys.exit('already patched')


def once(old, new):
    global s
    assert s.count(old) == 1, ('not unique', old[:80], s.count(old))
    s = s.replace(old, new)


# 1) 공용 데이터·모듈
once('  <script src="media/past-exam-quiz.js"></script>\n',
     '  <script src="media/past-exam-quiz.js"></script>\n  <script src="media/glossary-data.js"></script>\n  <script src="media/glossary.js"></script>\n  <script src="media/study-notes.js"></script>\n')

