once("      {id:'joseon-early',title:'조선 전기와 양난',desc:'조선 건국과 왕권 정비부터 임진왜란·병자호란까지',active:true,",
     "      {id:'joseon',title:'조선시대',desc:'건국·제도 정비와 양난부터 붕당·탕평·세도 정치와 달라진 사회까지',active:true,comic:'media/joseon-all-comic.html',parts:['joseon-early','joseon-late'],note:[],memory:''},\n"
     "      {id:'joseon-early',title:'조선 전기와 양난',desc:'조선 건국과 왕권 정비부터 임진왜란·병자호란까지',active:true,hidden:true,partOf:'joseon',partLabel:'전기·양난',partAnchor:'#early-part',")
once("{id:'joseon-late',title:\"조선 후기\",desc:\"붕당·탕평·세도 정치와 달라진 사회·경제\",active:true,",
     "{id:'joseon-late',title:\"조선 후기\",desc:\"붕당·탕평·세도 정치와 달라진 사회·경제\",active:true,hidden:true,partOf:'joseon',partLabel:'후기',partAnchor:'#late-part',")

lines = s.split('\n')
def find_line(prefix):
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    assert len(idx) == 1, (prefix, idx)
    return idx[0]

a = find_line("    var app=document.getElementById('app')")
b = find_line("    var quizzes={")
old_block = lines[a:b]
hero = [l for l in old_block if l.startswith('    function heroIllustration(')][0]
home = [l for l in old_block if l.startswith('    function home(')][0]
touch = [l for l in old_block if l.startswith("    var edgeStart") or l.startswith("    document.addEventListener('touch")]
msg = [l for l in old_block if l.startswith("    window.addEventListener('message'")][0]
hdr = [l for l in old_block if l.startswith('    function header(')][0]
step1 = [l for l in old_block if l.startswith('      if(step===1){')][0]
regex = re.search(r"x\.replace\((/\(.*?\)/g),'<span class=\"red\">\$1</span>'\)", step1).group(1)

home = home.replace("var cards=chapters.map(function(c,i){", "var cards=chapters.filter(function(c){return !c.hidden;}).map(function(c,i){")
home = home.replace('<span class="path-step"><b>3</b>빈칸 20</span>', '<span class="path-step"><b>3</b>빈칸 문제</span>')
home = home.replace('<span class="path-step"><b>4</b>기출 5</span>', '<span class="path-step"><b>4</b>기출 문제</span>')
assert 'chapters.filter' in home and '빈칸 문제' in home and '기출 문제' in home

new_block = r"""    var app=document.getElementById('app'),current=null,step=0,chapterPart='all';
    app.addEventListener('click',function(event){if(event.target.closest('#homeBrand'))home();});
    var stepSlugs=['webtoon','summary','quiz','mock'];
    function chapterById(id){return chapters.find(function(c){return c.id===id&&c.active;})||null;}
    /* 통합 장(조선시대)이면 지금 고른 범위의 원래 장들, 아니면 현재 장 하나 */
    function partChapters(){if(!current)return [];if(!current.parts)return [current];return current.parts.filter(function(id){return chapterPart==='all'||chapterPart===id;}).map(chapterById).filter(Boolean);}
    function routeId(){return current?(current.parts&&chapterPart!=='all'?chapterPart:current.id):null;}
    function routeUrl(){return current?'#chapter/'+encodeURIComponent(routeId())+'/'+stepSlugs[step]:location.pathname+location.search;}
    function saveRoute(replace){var prior=history.state&&history.state.hanq?history.state.depth:0;var state={hanq:true,chapterId:routeId(),step:step,depth:replace?prior:prior+1};history[replace?'replaceState':'pushState'](state,'',routeUrl());}
    function readRoute(){var m=location.hash.match(/^#chapter\/([^/]+)\/(webtoon|summary|quiz|mock)$/);if(!m)return null;var id;try{id=decodeURIComponent(m[1]);}catch(e){return null;}return chapterById(id)?{id:id,step:stepSlugs.indexOf(m[2])}:null;}
    function changeStep(next,silent){if(!current||next===step||next<0||next>3)return;step=next;if(!silent)saveRoute(false);renderLesson();window.scrollTo({top:0,behavior:'smooth'});}
    function goBack(){if(!current)return;var state=history.state;if(state&&state.hanq&&state.depth>0){history.back();return;}if(step>0){changeStep(step-1,true);}else{home(true);}saveRoute(true);}
    window.addEventListener('popstate',function(event){var state=event.state;if(state&&state.hanq&&state.chapterId){openChapter(state.chapterId,true,state.step);}else if(state&&state.hanq){home(true);}else{var route=readRoute();if(route)openChapter(route.id,true,route.step);else home(true);}});
""" + msg + '\n' + '\n'.join(touch) + r"""
    var stepNames=['웹툰 보기','요약 노트','빈칸','실전 모의'];
""" + hdr + '\n' + hero + '\n' + home + r"""
    function openChapter(id,silent,initialStep){var chapter=chapterById(id);if(!chapter){home(true);return;}var parent=chapter.partOf?chapterById(chapter.partOf):null;if(chapter.partOf&&!parent){home(true);return;}current=parent||chapter;chapterPart=parent?chapter.id:'all';step=typeof initialStep==='number'&&initialStep>=0&&initialStep<=3?initialStep:0;if(!silent)saveRoute(false);renderLesson();window.scrollTo({top:0,behavior:'smooth'});}
    /* 범위 바꾸기: 화면만 다시 그리고 풀던 답·확인 결과는 그대로 둔다 */
    function setPart(next){if(!current||!current.parts||next===chapterPart)return;if(next!=='all'&&current.parts.indexOf(next)<0)return;var key=step===2?currentQuizKey():null,mkey=step===3?currentMockKey():null;chapterPart=next;if(step===2){var qi=quizEntries().map(function(e){return e.key;}).indexOf(key);quizIndex=qi>=0?qi:0;}if(step===3){var mi=mockEntries().map(function(e){return e.key;}).indexOf(mkey);mockIndex=mi>=0?mi:0;}saveRoute(true);renderLesson(true);var picked=app.querySelector('input[name="chapterPart"]:checked');if(picked)picked.focus();}
    function partPicker(){if(!current.parts)return '';var opts=[['all','전체']].concat(current.parts.map(function(id){var c=chapterById(id);return [id,c?c.partLabel:id];}));return '<fieldset class="part-picker"><legend>볼 범위</legend>'+opts.map(function(o){return '<label class="part-option"><input type="radio" name="chapterPart" value="'+o[0]+'"'+(o[0]===chapterPart?' checked':'')+'><span>'+o[1]+'</span></label>';}).join('')+'</fieldset>';}
    var noteHighlight=""" + regex + r""";
    function noteCards(c){return '<div class="note-grid">'+c.note.map(function(n){return '<article class="note-card '+(n.title.indexOf('왕 순서')===0?'king-timeline':'')+'"><h3>'+n.title+'</h3><ul>'+n.items.map(function(x){return '<li>'+x.replace(noteHighlight,'<span class="red">$1</span>')+'</li>';}).join('')+'</ul></article>';}).join('')+'</div><div class="memory">기억 한 줄 · '+c.memory+'</div>';}
    function studyBlocks(c){var s=window.HANQ_STUDY&&window.HANQ_STUDY[c.id];if(!s)return '';var h='';
      if(s.flow&&s.flow.length)h+='<article class="study-block study-flow"><h3>흐름 한눈에</h3><ol class="flow-list">'+s.flow.map(function(f){return '<li><strong class="flow-title">'+escapeHTML(f.t)+'</strong>'+(f.cause?'<span class="flow-row"><b class="flow-tag cause">배경</b><span>'+escapeHTML(f.cause)+'</span></span>':'')+'<span class="flow-row"><b class="flow-tag change">'+(f.cause||f.result?'변화':'핵심')+'</b><span>'+escapeHTML(f.change)+'</span></span>'+(f.result?'<span class="flow-row"><b class="flow-tag result">결과</b><span>'+escapeHTML(f.result)+'</span></span>':'')+'</li>';}).join('')+'</ol></article>';
      if(s.compare&&s.compare.length)h+='<article class="study-block study-compare"><h3>헷갈리는 짝</h3>'+s.compare.map(function(p){return '<div class="pair"><p class="pair-title">'+escapeHTML(p.title)+'</p><div class="pair-cols"><p><b>'+escapeHTML(p.a[0])+'</b>'+escapeHTML(p.a[1])+'</p><p><b>'+escapeHTML(p.b[0])+'</b>'+escapeHTML(p.b[1])+'</p></div>'+(p.tip?'<p class="pair-tip">'+escapeHTML(p.tip)+'</p>':'')+'</div>';}).join('')+'</article>';
      if(s.recall&&s.recall.length)h+='<article class="study-block study-recall"><h3>떠올려 보기</h3><ol class="recall-list">'+s.recall.map(function(r){return '<li><details class="recall"><summary><span class="rq">'+escapeHTML(r.q)+'</span><span class="reveal-hint">답 보기</span></summary><p class="ra">'+escapeHTML(r.a)+'</p></details></li>';}).join('')+'</ol></article>';
      return h;}
    function summaryFor(c,multi){var orig=c.summaryType==='image'?'<img class="note-img" src="'+c.summary+'" alt="삼국시대 왕과 사건의 휴대폰용 원페이지 요약 노트"><details class="source-notes"><summary>요약 카드 글로 보기 ('+c.note.length+'개)</summary>'+noteCards(c)+'</details>':'<details class="source-notes"><summary>시험 단서 노트 전체 보기 (카드 '+c.note.length+'개)</summary>'+noteCards(c)+'</details>';return '<section class="summary-part" data-chapter="'+c.id+'">'+(multi?'<h3 class="part-title">'+c.title+'</h3>':'')+studyBlocks(c)+orig+'</section>';}
    function renderLesson(keep){clearAutoAdvance();app.classList.add('lesson-active');
      var quizCount=step===2||true?quizEntries().length:0;
      var steps='<div class="steps">'+stepNames.map(function(l,i){var name=i===2?l+' '+quizCount:l;return '<button class="step '+(i===step?'current':i<step?'done':'')+'" data-step="'+i+'"><span>'+(i<step?'✓':('0'+(i+1)))+'</span> '+name+'</button>';}).join('')+'</div>';
      var content='';
      if(step===0){var anchor=current.parts&&chapterPart!=='all'?((chapterById(chapterPart)||{}).partAnchor||''):'';var src=current.comic+anchor;content='<section class="panel comic-panel"><h2>이야기로 먼저 흐름 잡기</h2><p class="help">그림 아래 강조어를 보며 흐름과 사건을 연결해 보세요. 어려운 말은 장면 아래 ‘용어 풀이’를 눌러요.</p><a class="open-webtoon" href="'+src+'" target="_blank" rel="noopener">웹툰을 크게 열기 ↗</a><div class="watch-wrap"><iframe class="watch" title="'+current.title+' 학습 웹툰" src="'+src+'" loading="lazy"></iframe></div></section>';}
      if(step===1){var parts=partChapters();content='<section class="panel summary-panel"><h2>시대 흐름·시험 핵심 요약</h2><p class="help">흐름 → 헷갈리는 짝 → 떠올려 보기 순서로 읽고, 맨 아래 단서 노트로 확인해요. 어려운 말은 ‘용어 풀이’를 눌러 보세요.</p>'+parts.map(function(c){return summaryFor(c,parts.length>1||!!current.parts);}).join('')+'</section>';}
      if(step===2){content='<section class="panel quiz-panel"><h2>빈칸 '+quizCount+'문제</h2><p class="help">답을 확인해요. 맞히면 1초 뒤 다음 문제로 넘어가요.</p><div class="quiz-progress"><span id="quizPosition"></span><span id="quizScore"></span></div><div class="progress-track"><div class="progress-fill" id="quizProgress"></div></div><div class="quiz-jump"><label for="quizJump">문제 바로 가기</label><select id="quizJump"></select></div><div id="quiz"></div><div class="quiz-nav"><button class="prev-btn" id="prevQuestion" type="button">← 이전</button><button class="next-btn" id="nextQuestion" type="button">다음 →</button></div><button class="next-btn" id="backHome">목차로 돌아가기</button></section>';}
      if(step===3){content='<section class="panel mock-panel"><div class="mock-inner"><h2>실전 모의 · 기출 '+mockEntries().length+'문제</h2><p class="help">실제 시험 문제를 풀고, 틀린 단서만 다시 잡아요.</p><div class="quiz-progress"><span id="mockPosition"></span><span id="mockScore"></span></div><div class="progress-track"><div class="progress-fill" id="mockProgress"></div></div><div id="mock"></div><div class="quiz-nav mock-nav"><button class="prev-btn" id="prevMock" type="button">← 이전</button><button class="next-btn" id="nextMock" type="button">다음 →</button></div></div></section>';}
      app.innerHTML=header()+'<div class="module-head"><div class="module-actions"><button class="back" id="back" type="button">← 뒤로</button><button class="home-shortcut" id="moduleHome" type="button">⌂ 시대별 목차</button></div><h1>'+current.title+'</h1><p>'+current.desc+'</p></div>'+steps+partPicker()+content+'<nav class="mobile-nav" aria-label="학습 화면 이동"><button id="mobileBack" type="button">← 뒤로</button><button class="mobile-home" id="mobileHome" type="button">⌂ 홈 · 시대별 목차</button></nav>';
      app.querySelector('#back').addEventListener('click',goBack);app.querySelector('#moduleHome').addEventListener('click',function(){home();window.scrollTo({top:0,behavior:'smooth'});});app.querySelector('#mobileBack').addEventListener('click',goBack);app.querySelector('#mobileHome').addEventListener('click',function(){home();window.scrollTo({top:0,behavior:'smooth'});});app.querySelectorAll('.step').forEach(function(b){b.addEventListener('click',function(){changeStep(Number(b.dataset.step));});});
      app.querySelectorAll('input[name="chapterPart"]').forEach(function(r){r.addEventListener('change',function(){if(r.checked)setPart(r.value);});});
      if(step===1&&window.HanqGlossary){try{HanqGlossary.annotate(app.querySelectorAll('.summary-panel .study-block, .summary-panel .note-card'),{ctx:'s'});}catch(err){if(window.console)console.warn('glossary',err);}}
      if(step===2){if(keep)showQuizQuestion();else renderQuiz();app.querySelector('#prevQuestion').addEventListener('click',function(){moveQuiz(-1);});app.querySelector('#nextQuestion').addEventListener('click',function(){moveQuiz(1);});app.querySelector('#quizJump').addEventListener('change',function(event){jumpQuiz(event.target.value);});app.querySelector('#backHome').addEventListener('click',home);}
      if(step===3){if(keep)showMockQuestion();else renderMock();app.querySelector('#prevMock').addEventListener('click',function(){moveMock(-1);});app.querySelector('#nextMock').addEventListener('click',function(){moveMock(1);});}
    }"""
new_block = new_block.replace("var quizCount=step===2||true?quizEntries().length:0;", "var quizCount=quizEntries().length;")
lines[a:b] = new_block.split('\n')
s = '\n'.join(lines)

# 3) 빈칸·실전 모의: 문제마다 고유 키로 상태를 기억(범위를 바꿔도 답·확인 결과 유지)
lines = s.split('\n')
qa = find_line("    var quizState=[],quizAnswers=[],quizIndex=0,autoAdvanceTimer=null;")
qb = find_line("    function moveMock(delta)")
quiz_block = r"""    var quizStore={},quizIndex=0,autoAdvanceTimer=null;
    function clearAutoAdvance(){if(autoAdvanceTimer){clearTimeout(autoAdvanceTimer);autoAdvanceTimer=null;}}
    /* 시대마다 원래와 같은 방식으로 20문항을 고른다(통합 장은 각 부분의 20문항을 그대로 이어 붙임) */
    function sampleIndexes(len){var count=Math.min(20,len);return Array.from({length:count},function(_,i){return Math.floor(i*len/count);});}
    function quizEntries(){return partChapters().reduce(function(all,c){var pool=quizzes[c.id]||[];return all.concat(sampleIndexes(pool.length).map(function(pi){return {key:c.id+':'+pi,item:pool[pi]};}));},[]);}
    function practiceQuestions(){return quizEntries().map(function(e){return e.item;});}
    function quizStateFor(key){return quizStore[key]||(quizStore[key]={checked:false,correct:false,answer:''});}
    function currentQuizKey(){var e=quizEntries()[quizIndex];return e?e.key:null;}
    function renderQuiz(){clearAutoAdvance();quizStore={};quizIndex=0;showQuizQuestion();}
    function retryQuiz(){clearAutoAdvance();quizEntries().forEach(function(e){delete quizStore[e.key];});quizIndex=0;showQuizQuestion();}
    function updateQuizProgress(){var entries=quizEntries(),states=entries.map(function(e){return quizStateFor(e.key);}),done=states.filter(function(item){return item.checked;}).length,correct=states.filter(function(item){return item.checked&&item.correct;}).length;app.querySelector('#quizPosition').textContent=(quizIndex+1)+' / '+entries.length;app.querySelector('#quizScore').textContent='⭕ 정답 '+correct+' · 확인 '+done;app.querySelector('#quizProgress').style.width=((quizIndex+1)/entries.length*100)+'%';}
    /* 용어 풀이가 이 문제의 답을 말해 버리지 않도록 답 낱말이 들어간 풀이는 빼다 */
    function answerTokens(item){var out=[];(item.a||[]).forEach(function(a){String(a).split(/[^가-힣A-Za-z0-9]+/).forEach(function(t){t=norm(t);if(t.length>=2)out.push(t);});var w=norm(a);if(w.length>=2)out.push(w);});return out;}
    function noLeak(item){var toks=answerTokens(item);return function(e){var hay=norm([e.term,e.short,e.detail].concat(e.match||[]).join(' '));return !toks.some(function(t){return hay.indexOf(t)>=0;});};}
    function showQuizQuestion(){clearAutoAdvance();var entries=quizEntries(),list=entries.map(function(e){return e.item;}),host=app.querySelector('#quiz'),nav=app.querySelector('.quiz-nav'),prev=app.querySelector('#prevQuestion'),next=app.querySelector('#nextQuestion');syncQuizJump(list);if(quizIndex>=list.length){var states=entries.map(function(e){return quizStateFor(e.key);}),correct=states.filter(function(item){return item.checked&&item.correct;}).length,wrong=states.map(function(state,i){return {state:state,item:list[i],index:i};}).filter(function(row){return !row.state.correct;});app.querySelector('#quizPosition').textContent='완료';app.querySelector('#quizScore').textContent='⭕ 정답 '+correct+' / '+list.length;app.querySelector('#quizProgress').style.width='100%';host.innerHTML='<div class="result-screen"><h3>여기까지 풀었어요!</h3><div class="result-score">정답 '+correct+' / '+list.length+'</div>'+(wrong.length?'<h4>오답 노트 · 틀리거나 건너뛴 문제</h4>'+wrong.map(function(row){return '<article class="review-item"><strong>'+(row.index+1)+'. '+quizText(row.item.q)+'</strong><p>'+(row.state.checked?'다시 볼 내용':'아직 풀지 않았어요.')+' · 정답: '+escapeHTML(row.item.a[0])+'</p><p>'+quizText(row.item.why)+'</p><div class="remember"><strong>이건 이렇게 외워!</strong><span>'+quizText(row.item.cue)+'</span></div></article>';}).join(''):'<p>모든 문제를 맞혔어요. 잘 기억하고 있어요!</p>')+'<div class="result-actions"><button class="check-one" id="retryQuiz" type="button">처음부터 다시 풀기</button></div></div>';nav.hidden=true;app.querySelector('#retryQuiz').addEventListener('click',retryQuiz);return;}nav.hidden=false;updateQuizProgress();var item=list[quizIndex],state=quizStateFor(entries[quizIndex].key);host.innerHTML='<article class="question"><div class="qtop"><span class="qnum">'+String(quizIndex+1).padStart(2,'0')+'</span><div class="qtext"><small class="qsection">'+escapeHTML(item.section)+'</small>'+quizText(item.q)+'</div></div><input class="answer" id="quizAnswer" type="text" autocomplete="off" aria-label="답 입력" placeholder="답을 입력하세요"><button class="check-one" id="checkAnswer" type="button">정답 확인</button><div class="feedback" id="quizFeedback" aria-live="polite"></div></article>';var input=app.querySelector('#quizAnswer'),feedback=app.querySelector('#quizFeedback'),check=app.querySelector('#checkAnswer');input.value=state.answer||'';input.addEventListener('input',function(){state.answer=input.value;if(state.checked){state.checked=false;state.correct=false;feedback.className='feedback';feedback.textContent='';check.textContent='정답 확인';updateQuizProgress();}});check.addEventListener('click',checkCurrentAnswer);input.addEventListener('keydown',function(event){if(event.key==='Enter')checkCurrentAnswer();});if(state.checked){showAnswerFeedback(item,state,feedback,false,quizIndex);check.textContent='다시 확인';}prev.disabled=quizIndex===0;next.textContent=quizIndex===list.length-1?'결과 보기 →':'다음 →';if(window.HanqGlossary){try{HanqGlossary.annotate([host.querySelector('.qtext')],{ctx:'q',filter:noLeak(item),after:function(){return feedback;}});}catch(err){if(window.console)console.warn('glossary',err);}}}
    function showAnswerFeedback(item,state,feedback,autoadvance,index){feedback.className='feedback show '+(state.correct?'good':'bad');if(state.correct){feedback.innerHTML='<div class="right-wrap"><span class="right-mark" aria-hidden="true">✓</span><strong>정답이에요!</strong><small>'+(autoadvance?'잠깐만요, 다음 문제로 넘어가요.':'')+'</small></div>';}else{var cue=item.cue;feedback.innerHTML='<div class="wrong-hit"><span class="wrong-mark" aria-hidden="true">×</span><div class="wrong-copy"><span class="feedback-title">앗, 아깝다!</span><strong>정답은 '+escapeHTML(item.a[0])+'이에요</strong></div></div><section class="wrong-note"><div class="note-label">📝 오답 노트</div><p>'+quizText(item.why)+'</p><div class="remember"><strong>여기서 빡! 이거 외워!</strong><span>'+quizText(cue)+'</span></div></section>';}}
    function checkCurrentAnswer(){var entry=quizEntries()[quizIndex];if(!entry)return;var item=entry.item,state=quizStateFor(entry.key),input=app.querySelector('#quizAnswer'),feedback=app.querySelector('#quizFeedback'),check=app.querySelector('#checkAnswer'),value=norm(input.value);if(!value){feedback.className='feedback show bad';feedback.textContent='답을 먼저 입력해 주세요.';input.focus();return;}clearAutoAdvance();state.answer=input.value;state.checked=true;state.correct=item.a.some(function(answer){return norm(answer)===value;});showAnswerFeedback(item,state,feedback,state.correct,quizIndex);updateQuizProgress();if(state.correct){check.disabled=true;input.disabled=true;autoAdvanceTimer=setTimeout(function(){autoAdvanceTimer=null;quizIndex++;showQuizQuestion();app.querySelector('#quiz').scrollIntoView({behavior:'smooth',block:'start'});},1000);}else{check.textContent='다시 확인';feedback.scrollIntoView({behavior:'smooth',block:'nearest'});}}
    function moveQuiz(delta){clearAutoAdvance();quizIndex=Math.max(0,Math.min(practiceQuestions().length,quizIndex+delta));showQuizQuestion();app.querySelector('#quiz').scrollIntoView({behavior:'smooth',block:'start'});}
    function syncQuizJump(list){var jump=app.querySelector('#quizJump');if(!jump)return;if(jump.options.length!==list.length+1){jump.innerHTML='<option value="" disabled>완료 · 다시 볼 문제 선택</option>'+list.map(function(_,i){return '<option value="'+i+'">'+(i+1)+'번 문제</option>';}).join('');}jump.value=quizIndex<list.length?String(quizIndex):'';}
    function jumpQuiz(value){clearAutoAdvance();var index=value===''?NaN:Number(value);if(!Number.isInteger(index)||index<0||index>=practiceQuestions().length)return;quizIndex=index;showQuizQuestion();}

    var mockStore={},mockIndex=0;
    function mockEntries(){return partChapters().reduce(function(all,c){var l=(window.PAST_EXAM_QUIZZES&&window.PAST_EXAM_QUIZZES[c.id])||[];return all.concat(l.map(function(q){return {key:c.id+':'+q.exam+'-'+q.number,item:q};}));},[]);}
    function mockList(){return mockEntries().map(function(e){return e.item;});}
    function mockStateFor(key){return mockStore[key]||(mockStore[key]={selected:0,checked:false,correct:false});}
    function currentMockKey(){var e=mockEntries()[mockIndex];return e?e.key:null;}
    function renderMock(){mockStore={};mockIndex=0;showMockQuestion();}
    function retryMock(){mockEntries().forEach(function(e){delete mockStore[e.key];});mockIndex=0;showMockQuestion();}
    function mockScroll(){var host=app.querySelector('#mock');if(host)host.scrollIntoView({behavior:'smooth',block:'start'});}
    function updateMockProgress(){var entries=mockEntries(),states=entries.map(function(e){return mockStateFor(e.key);}),done=states.filter(function(x){return x.checked;}).length,correct=states.filter(function(x){return x.correct;}).length;app.querySelector('#mockPosition').textContent=(mockIndex+1)+' / '+entries.length;app.querySelector('#mockScore').textContent='정답 '+correct+' · 확인 '+done;app.querySelector('#mockProgress').style.width=((mockIndex+1)/entries.length*100)+'%';}
    function showMockQuestion(){var entries=mockEntries(),list=entries.map(function(e){return e.item;}),host=app.querySelector('#mock'),nav=app.querySelector('.mock-nav'),prev=app.querySelector('#prevMock'),next=app.querySelector('#nextMock');if(!list.length){host.innerHTML='<p class="empty">준비 중입니다.</p>';nav.hidden=true;return;}if(mockIndex>=list.length){var states=entries.map(function(e){return mockStateFor(e.key);}),correct=states.filter(function(x){return x.correct;}).length;var wrong=states.map(function(state,i){return {state:state,item:list[i]};}).filter(function(row){return !row.state.correct;});app.querySelector('#mockPosition').textContent='완료';app.querySelector('#mockScore').textContent='정답 '+correct+' / '+list.length;app.querySelector('#mockProgress').style.width='100%';nav.hidden=true;host.innerHTML='<div class="result-screen"><h3>실전 모의 완료</h3><div class="result-score">정답 '+correct+' / '+list.length+'</div>'+(wrong.length?'<h4>다시 볼 문제</h4>'+wrong.map(function(row){var q=row.item;return '<article class="review-item"><strong>제'+q.exam+'회 '+q.number+'번 · '+escapeHTML(q.topic)+'</strong><p>정답 '+['','①','②','③','④','⑤'][q.answer]+' · '+(row.state.checked?'내 선택 '+['','①','②','③','④','⑤'][row.state.selected]:'건너뜀')+'</p><p>'+escapeHTML(q.why)+'</p><div class="remember"><strong>여기서 외워!</strong><span>'+escapeHTML(q.remember)+'</span></div></article>';}).join(''):'<p>'+list.length+'문제 모두 맞혔어요!</p>')+'<div class="result-actions"><button class="check-one" id="retryMock" type="button">다시 풀기</button></div></div>';app.querySelector('#retryMock').addEventListener('click',retryMock);return;}nav.hidden=false;updateMockProgress();var q=list[mockIndex],state=mockStateFor(entries[mockIndex].key),symbols=['','①','②','③','④','⑤'];host.innerHTML='<article class="mock-question"><div class="mock-meta"><strong>제'+q.exam+'회 심화 · '+q.number+'번</strong><span>'+q.points+'점</span></div><div class="mock-image-wrap"><img class="mock-image" src="'+q.image+'" alt="제'+q.exam+'회 심화 '+q.number+'번 기출 문제 원문" loading="lazy"></div><a class="mock-enlarge" href="'+q.image+'" target="_blank" rel="noopener">문제 크게 보기 ↗</a><div class="mock-select-title">답을 골라 주세요</div><div class="mock-choices">'+symbols.slice(1).map(function(sym,i){var n=i+1;return '<button type="button" class="mock-choice '+(state.selected===n?'selected ':'')+(state.checked&&q.answer===n?'right ':'')+(state.checked&&state.selected===n&&!state.correct?'wrong ':'')+'" data-choice="'+n+'" '+(state.checked?'disabled':'')+' aria-label="'+sym+'번 선택">'+sym+'</button>';}).join('')+'</div>'+(state.checked?'<div class="mock-feedback '+(state.correct?'good':'bad')+'" aria-live="polite">'+(state.correct?'<div class="right-wrap"><span class="right-mark" aria-hidden="true">✓</span><strong>정답! '+escapeHTML(q.topic)+'</strong></div>':'<div class="wrong-hit"><span class="wrong-mark" aria-hidden="true">×</span><div class="wrong-copy"><span class="feedback-title">이 단서만 잡자!</span><strong>정답은 '+symbols[q.answer]+'번</strong></div></div><section class="wrong-note"><div class="note-label">📝 오답 노트</div><p>'+escapeHTML(q.why)+'</p><div class="remember"><strong>여기서 빡! 이거 외워!</strong><span>'+escapeHTML(q.remember)+'</span></div></section>')+'</div>':'<button class="check-one" id="checkMock" type="button" '+(state.selected?'':'disabled')+'>정답 확인</button>')+'</article>';host.querySelectorAll('.mock-choice').forEach(function(btn){btn.addEventListener('click',function(){state.selected=Number(btn.dataset.choice);host.querySelectorAll('.mock-choice').forEach(function(x){x.classList.toggle('selected',x===btn);});host.querySelector('#checkMock').disabled=false;});});var check=host.querySelector('#checkMock');if(check)check.addEventListener('click',function(){state.checked=true;state.correct=state.selected===q.answer;showMockQuestion();var feedback=app.querySelector('.mock-feedback');if(feedback&&!state.correct)feedback.scrollIntoView({behavior:'smooth',block:'nearest'});});prev.disabled=mockIndex===0;next.textContent=mockIndex===list.length-1?'결과 보기 →':'다음 →';}"""
